  "claim": {
    "component_id": "C063.component",
    "value": "Broader deployment requires staged confirmation.",
    "scope": "Expansion beyond the tested cohort, concurrency range, versions, and operating conditions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P040",
