      ],
      "support_status": "SUFFICIENT",
      "rationale": "P040 explicitly supplies the expansion requirement and its bounds; P029 specifies staging, monitoring, and rollback for a rollout that meets benefit and safety criteria."
    }
  },
  "signal_basis": {
    "component_id": "C063.signal_basis",
    "value": "A controlled reduction in canary concurrency produces observed trajectories of queue depth, completion rate, and phase durations, compared with baseline and any unchanged pool. Shared-resource effects and nonlinear saturation can limit transfer of that response beyond the tested setting.",
    "scope": "The tested cohort, concurrency range, versions, and operating conditions; observing the response does not establish performance under broader deployment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
