          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the perturbation, response measurements, comparisons, and transfer limitations. P025 clarifies that observation is hypothetical here, as assumed by the question."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C063.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical bridge is required for this supported limitation on generalization."
    }
  },
  "rationale": "A response to one bounded perturbation provides evidence within the tested conditions. Nonlinear behavior and shared-resource effects can change the response during expansion, so requiring staged confirmation is warranted. This claim does not itself authorize broader deployment.",
  "uncertainty": "The assumed response leaves outcomes beyond the tested conditions unresolved; staged confirmation addresses that uncertainty without guaranteeing successful expansion.",
  "anomalies": []
}
